INSERT INTO `filmy` (`id`, `tytul`, `tytul_oryginalny`, `gatunek`, `rok`, `ocena`, `rezyser`, `czas_trwania`, `jezyk`, `ilosc_dostepnych`, `budzet`, `produkcja`, `nagrody`, `cena`, `opis`, `okladka`, `tmdb_id`, `imdb_id`, `typ_plyty_id`, `czy_ulubiony`) VALUES
(4, 'Borat', NULL, 'Comedy', 2006, 7.4, 'Larry Charles', 84, 'English, Romanian, Hebrew, Polish, Armenian', 9, NULL, 'N/A', 'Nominated for 1 Oscar. 20 wins & 34 nominations total', 6.27, 'Borat Sagdiyev is a TV reporter of a popular show in Kazakhstan as Kazakhstan\'s sixth most famous man and a leading journalist. He is sent from his home to America by his government to make a documentary about American society and culture. Borat takes a course in New York City to understand American humor. While watching Baywatch on TV, Borat discovers how beautiful their women are in the form of C. J. Parker, who was played by actress Pamela Anderson who hails from Malibu, California. He decides to go on a cross-country road trip to California in a quest to make her his wife and take her back to his country. On his journey Borat and his producer encounter a country full of strange and wonderful Americans, real people in real chaotic situations with hysterical consequences.', 'https://m.media-amazon.com/images/M/MV5BMTk0MTQ3NDQ4Ml5BMl5BanBnXkFtZTcwOTQ3OTQzMw@@._V1_QL75_UY562_CR0,0,380,562_.jpg', NULL, NULL, 2, 0),
(5, 'Back to the Future', NULL, 'Adventure, Comedy, Sci-Fi', 1985, 8.5, 'Robert Zemeckis', 116, 'English', 2, 5.00, 'N/A', 'Won 1 Oscar. 30 wins & 28 nominations total', 12.00, 'Marty McFly, a typical American teenager of the Eighties, is accidentally sent back to 1955 in a plutonium-powered DeLorean \"time machine\" invented by a slightly mad scientist. During his often hysterical, always amazing trip back in time, Marty must make sure his teenage parents-to-be meet and fall in love to get back to the future.', 'https://m.media-amazon.com/images/M/MV5BZmM3ZjE0NzctNjBiOC00MDZmLTgzMTUtNGVlOWFlOTNiZDJiXkEyXkFqcGc@._V1_QL75_UX380_CR0,14,380,562_.jpg', NULL, NULL, 2, 0),
(8, 'Koszmar z Ulicy Wiązów', 'A Nightmare on Elm Street', 'Horror', 1984, 7.4, 'Wes Craven', 91, 'English', 8, 1800000.00, 'New Line Cinema, Smart Egg Pictures, Media Home Entertainment, Cinema 84, The Elm Street Venture', '7 wins & 8 nominations total', 10.00, 'Czwórkę nastoletnich przyjaciół męczą koszmary. Pojawia się w nich ten sam facet z poparzoną twarzą w kapeluszu i rękawicy zakończonej brzytwami. Z początku nie traktują sprawy poważnie. Zmienia to się diametralnie kiedy ginie Tina. Podejrzenie spada na jej chłopaka Roda, ponieważ to on był z nią tej straszliwej nocy. Nancy wierząc w niewinność przyjaciela odkrywa przerażającą prawdę dotyczącą człowieka z jej snów.', 'https://image.tmdb.org/t/p/w500/smYGD7smBa4VYEqH2Ho87m0Fp7Q.jpg', 377, 'tt0087800', 2, 0),
(11, 'Resident Evil', 'Resident Evil', 'Horror, Sci-Fi, Przygodowy', 2026, 7.5, 'Zach Cregger', 94, 'English', 4, 75000000.00, 'Constantin Film, Subconscious, Vertigo Entertainment, Davis Films, Columbia Pictures, PlayStation Pr', '', 7.25, 'Bryan pracuje jako kurier medyczny, przewożąc organy między szpitalami na potrzeby przeszczepów. Późną zimową nocą otrzymuje zlecenie dostarczenia pojemnika do szpitala Raccoon General Hospital w Raccoon City w Kolorado. Podczas jazdy przez góry rozprasza się i potrąca kobietę. Gdy próbuje zawieźć ją do szpitala, odkrywa, że mieszkańcy miasta zaczynają przemieniać się w groteskowe stworzenia.', 'https://image.tmdb.org/t/p/w500/gAgWJhUSQWCgtKR8170nMkYlBda.jpg', 1423191, 'tt35538033', 2, 0),
(12, 'W sercu dziczy', 'Heart of the Beast', 'Przygodowy, Thriller', 2026, 7.6, 'David Ayer', 101, 'English', 6, 82000000.00, 'Paramount Pictures, Wild Chickens Productions, Temple Hill Entertainment, Domain Entertainment, Gulf', '1 nomination total', 9.91, 'Po tragicznej katastrofie lotniczej, oficer sił specjalnych James Belmont i jego pies bojowy Odin znajdują się w samym sercu alaskańskiej dziczy. Razem są zmuszeni do brutalnej walki o przetrwanie w obliczu żywiołów.', 'https://image.tmdb.org/t/p/w500/eGRIWQswCb5Jz1KHrT4ir1dXxDD.jpg', 1263337, 'tt7526136', 3, 0),
(13, 'Odyseja', 'The Odyssey', 'Przygodowy, Akcja, Fantasy', 2026, 8.0, 'Christopher Nolan', 173, 'English', 6, 250000000.00, 'Universal Pictures, Syncopy', '4 wins total', 14.28, 'Odyseusz, legendarny grecki król Itaki, po wojnie trojańskiej wyrusza w długą i niebezpieczną podróż do domu, opisując swoje spotkania z mitycznymi istotami, takimi jak cyklop Polifem, syreny i czarownica-bogini Circe.', 'https://image.tmdb.org/t/p/w500/1g2v4Gg8kVe6P1p5Tz5IA69BPBN.jpg', 1368337, 'tt33764258', 2, 0),
(14, 'Projekt Hail Mary', 'Project Hail Mary', 'Sci-Fi, Przygodowy', 2026, 8.6, 'Phil Lord', 157, NULL, 2, 200000000.00, 'Lord Miller, Amazon MGM Studios, Pascal Pictures, Open Invite Entertainment, Waypoint Entertainment', '12 wins & 15 nominations total', 8.91, 'Nauczyciel nauk ścisłych Ryland Grace budzi się na statku kosmicznym lata świetlne od domu, nie pamiętając, kim jest ani jak się tam znalazł. Gdy wraca mu pamięć, zaczyna odkrywać swoją misję: rozwiązać zagadkę tajemniczej substancji powodującej wygaśnięcie słońca. Musi wykorzystać swoją wiedzę naukową i niekonwencjonalne pomysły, aby ocalić wszystko na Ziemi przed zagładą, ale nieoczekiwana przyjaźń oznacza, że być może nie będzie musiał robić tego sam.', 'https://image.tmdb.org/t/p/w500/sQWgdoo3qM6dMLdpfXD804XZhwY.jpg', 687163, 'tt12042730', 2, 0),
(15, 'Spider-Man: Całkiem nowy dzień', 'Spider-Man: Brand New Day', 'Sci-Fi, Akcja, Przygodowy', 2026, 8.5, 'Destin Daniel Cretton', 145, 'English', 6, 225000000.00, 'Marvel Studios, Columbia Pictures, Pascal Pictures, TSG Entertainment', '1 nomination total', 11.33, 'Walcząc z przestępczością w Nowym Jorku, który nie zna już jego imienia, w pełni poświęcił się ochronie miasta. Gdy rosnące wymagania zaczynają go przytłaczać, presja wywołuje zaskakującą fizyczną przemianę, która zagraża jego istnieniu, podczas gdy nowy, niepokojący schemat zbrodni prowadzi do pojawienia się jednego z najpotężniejszych przeciwników, z jakimi kiedykolwiek się zmierzył.', 'https://image.tmdb.org/t/p/w500/sp8BH41oNdYwIKQFswqluNYa3SM.jpg', 969681, 'tt22084616', 2, 0),
(16, 'Inna mamusia', 'Other Mommy', 'Horror, Tajemnica', 2026, 6.3, 'Rob Savage', 93, 'English', 2, 18000000.00, 'Spin a Black Yarn, Blumhouse Atomic', '', 8.62, 'Dorastająca pośród małżeńskich konfliktów rodziców ośmioletnia Bela staje twarzą w twarz ze złowrogą istotą wychodzącą z jej szafy.', 'https://image.tmdb.org/t/p/w500/lmXeTaFtPrlAReFfG5fRTaSnUmp.jpg', 1400837, 'tt36586020', 2, 0),
(17, 'Witajcie w Hope', '호프', 'Sci-Fi, Tajemnica, Akcja', 2026, 6.8, '나홍진', 157, '한국어/조선말', 3, 46000000.00, 'Forged Films, Plus M Entertainment, Westworld Story', '2 nominations total', 5.71, 'Na obrzeżach odległego miasta portowego dokonuje się tajemniczego odkrycia. Mieszkańcy desperacko walczą o przetrwanie z czymś, z czym nigdy wcześniej się nie zetknęli.', 'https://image.tmdb.org/t/p/w500/obkrTl9yOAr8Pl50YK7ou4gc0We.jpg', 1058424, 'tt27369017', 3, 0),
(18, 'Historia Derry', 'A Story of Derry', 'Dramat, Horror, Tajemnica', 2026, 6.8, 'Tazbah Chavez', 30, 'English', 2, NULL, 'Rideback, Vertigo Entertainment, Warner Bros. Television, FiveTen Productions, K Plus Ultra, Double ', '', 14.23, 'Setki lat przed Pennywise’em troje młodych ludzi trafia do Zachodniego Lasu, gdzie spotyka pradawne zło.', 'https://image.tmdb.org/t/p/w500/i4nQn6GJznN02EcGOQCetNoU4mt.jpg', 1813355, 'tt50389959', 2, 0),
(19, 'Apokalipsa Z: Nowy świat', 'Apocalipsis Z: Nuevo mundo', 'Akcja, Thriller, Horror', 2026, 6.2, 'Carles Torrens', 96, 'Español', 2, NULL, 'Nostromo Pictures', '', 6.30, 'Po wybuchu epidemii wirusa TSJ Wyspy Kanaryjskie stały się ostatnią ostoją Europy. Kiedy do Madrytu wyrusza ekipa w poszukiwaniu zapasów, do zespołu dołącza Roberto, którego intencje budzą wątpliwości. Otoczeni przez zarażonych i rozdarci między wzajemnymi zobowiązaniami, walczą o przetrwanie, mierząc się z dylematem: ratować siebie czy zaryzykować wszystko dla tego, co pozostało z ludzkości.', 'https://image.tmdb.org/t/p/w500/ptWQV5lfa91U1ndxW566kYTvKo6.jpg', 1507696, 'tt37522541', 3, 0),
(20, 'Strzeż się', 'Beware Boiúna', 'Horror, Thriller, Akcja', 2026, 6.1, 'Mike P. Nelson', 104, 'English, Português', 8, NULL, 'Constantin Film, JB Pictures, Jaguar Bite, North.Five.Six.', '', 14.94, 'Akcja filmu rozgrywa się w głębi Amazonii, gdzie misja medyczna szybko wymyka się spod kontroli. Bohaterowie budzą bowiem do życia Boiúnę – gigantycznego, starożytnego drapieżnika, który powraca, by odzyskać swoje terytorium. W miejscu, w którym natura dyktuje własne zasady, uczestnicy wyprawy muszą zrobić wszystko, by przeżyć.', 'https://image.tmdb.org/t/p/w500/7mI13sTZcuwWEIUK9fckAb8Zmba.jpg', 1244523, 'tt10377864', 2, 0),
(21, 'Godzilla Minus Zero', 'ゴジラ-0.0', 'Sci-Fi, Horror, Akcja', 2026, 7.7, 'Takashi Yamazaki', 135, '日本語, English', 5, 15000000.00, 'TOHO, Robot Communications, TOHO Studios', '', 11.28, 'Akcja rozgrywa się w 1949 roku; rodzina Shikishimów stawia czoła nowej katastrofie dwa lata po przetrwaniu wcześniejszego starcia z legendarnym potworem.', 'https://image.tmdb.org/t/p/w500/t8l4SpAe0napDOIYlj4vgYGp7TQ.jpg', 1381071, 'tt34384661', 2, 0),
(22, 'Avengers: Doomsday', 'Avengers: Doomsday', 'Sci-Fi, Akcja, Przygodowy', 2026, NULL, 'Joe Russo', 165, 'English', 3, NULL, 'Marvel Studios, Kevin Feige Productions, AGBO', '2 nominations total', 12.57, 'Bohaterowie z trzech różnych wszechświatów zmierzają ku śmiertelnie niebezpiecznej konfrontacji i stają w obliczu egzystencjalnego zagrożenia, z jakim nigdy wcześniej się nie spotkali.', 'https://image.tmdb.org/t/p/w500/5pOEr3ypuPhrXACdeesHj01VAM8.jpg', 1003596, 'tt21357150', 3, 0),
(23, 'Nie poddamy się', 'Serangan Balik', 'Akcja, Kryminał, Thriller', 2026, 7.1, 'Sidharta Tata', 140, 'Bahasa indonesia, , English', 4, NULL, 'Mowin Pictures', '', 11.45, 'Gdy bezwzględny gang napada na jego położony na odludziu dom, targany poczuciem winy weteran oraz wnuki, które ledwie zna, muszą połączyć ze sobą siły, aby przetrwać.', 'https://image.tmdb.org/t/p/w500/eH7BUSUy3cyzlCTZpMU95U5DKq8.jpg', 1616687, 'tt39370926', 3, 0),
(24, 'Ramayana: Narodziny Legendy', 'रामायणम्', 'Fantasy, Akcja, Przygodowy', 2026, 7.5, 'Nitesh Tiwari', 195, 'हिन्दी, ', 2, 260000000.00, 'Monster Mind Creations, Prime Focus Studios, DNEG', '', 13.35, 'Starożytna epopeja opowiada historię młodego księcia i księżniczki, których małżeństwo i późniejsze wygnanie stanowią początek legendarnej podróży. Ich historia o miłości, obowiązku i przeznaczeniu przygotowuje grunt pod kolejne, większe wyzwania.', 'https://image.tmdb.org/t/p/w500/gOWnXaBxqT6k2y40hKfYU6c0Ym.jpg', 656908, 'tt27988879', 2, 0),
(25, 'The Mongoose', 'The Mongoose', 'Akcja, Thriller', 2026, 6.2, 'Mark Vanselow', 98, 'English', 3, NULL, 'Code Entertainment, The Solution', '', 10.69, 'Były komandos trafia w sam środek śmiertelnej gry w kotka i myszkę, gdy niebezpieczna misja ujawnia mroczny spisek. Ścigany przez bezwzględnych najemników, musi polegać na swoich zabójczych instynktach, by przetrwać polowanie i wyrównać rachunki.', 'https://image.tmdb.org/t/p/w500/eSS5mvSG84UUuvtbHel5Yu3Wik4.jpg', 1294189, 'tt13611778', 2, 0),
(26, 'Coco', 'Coco', 'Familijny, Animacja, Muzyczny, Przygodowy', 2017, 8.2, 'Lee Unkrich', 108, 'English, Español', 9, 175000000.00, 'Pixar', 'Won 2 Oscars. 113 wins & 42 nominations total', 10.95, 'Film opowiada o historii małego chłopca - Miguela, który próbuje rozwiązać pewną tajemnicę rodzinną. Za sprawą nieoczekiwanych wydarzeń dochodzi do spotkania chłopca i rodziny, żywej jak i martwej.', 'https://image.tmdb.org/t/p/w500/yMapvyFKryN8lgR1o0wD4tsCUw3.jpg', 354912, 'tt2380307', 2, 0),
(27, 'Żołnierz widmo', 'Ghost Soldier', 'Akcja, Thriller', 2026, 8.7, 'William Eubank', 90, 'English', 8, NULL, 'Columbia Pictures, Mandalay Pictures, Project X Entertainment, TSG Entertainment', '', 12.94, 'Henry „Fitz” Fitzgerald przez lata żył w ukryciu, z dala od cywilizacji, skrywając przeszłość, o której wie niewielu. Kiedy jednak potężna zagraniczna korporacja wkracza do jego rodzinnego miasta, by przejąć ziemię sąsiadów dla ogromnego zysku, Fitz musi ujawnić swoją prawdziwą tożsamość: jest byłym żołnierzem sił specjalnych i konstruktorem zaawansowanej broni. Wyposażony w eksperymentalne technologie, zabójcze umiejętności bojowe oraz niezachwiany kodeks sprawiedliwości, Fitz wypowiada jednoosobową wojnę przeciwnikowi, który zupełnie nie spodziewał się takiego przeciwnika.', 'https://image.tmdb.org/t/p/w500/8Y4oJ5iUs3hgPcDB3SIEmsNYjZk.jpg', 1562642, 'tt38686316', 2, 0),
(28, 'Verity. Coraz większy mrok', 'Verity', 'Tajemnica, Thriller', 2026, 7.0, 'Michael Showalter', 117, 'English', 10, 40000000.00, 'Eat the Cat, Semi-Formal Productions, Somewhere Pictures, Shiny Penny Productions, Heartbones Entert', '', 8.20, 'Lowen Ashleigh, początkująca pisarka, zostaje zatrudniona w tajemniczych okolicznościach jako ghostwriterka Verity Crawford. Zlecenie przybiera mroczny obrót po odkryciu przerażających notatek autobiograficznych, a dodatkowo jej relacje z Jeremym, mężem mocodawczyni, stają się coraz bardziej niejednoznaczne. W obliczu serii śmiertelnie niebezpiecznych rodzinnych tajemnic Lowen próbuje oddzielić fikcję od rzeczywistości.', 'https://image.tmdb.org/t/p/w500/sKrVmUkFZhBVf4NdTZTm1Nti3eI.jpg', 1283515, 'tt32261958', 2, 0),
(29, 'Czarna kula', 'La bola negra', 'Dramat, Wojenny', 2026, 8.0, 'Javier Ambrossi', 159, 'Español, English, Italiano', 6, 11100000.00, 'Movistar Plus, Le Pacte, El Deseo, Telefónica Audiovisual Digital, Los Esquiadores', '4 wins & 6 nominations total', 7.68, 'Powiązane ze sobą historie trzech mężczyzn z trzech różnych epok. Trzy życia ściśle ze sobą powiązane seksualnością i pożądaniem, bólem i dziedzictwem, inspirowane jednym z ostatnich niedokończonych dzieł Federico Garcii Lorci.', 'https://image.tmdb.org/t/p/w500/t1azKLExwUxKj6v6m2L535evuRa.jpg', 1422041, 'tt35511966', 2, 0),
(30, 'Ebenezer Scrooge. Opowieść wigilijna', 'Ebenezer', 'Fantasy, Komedia', 2026, 7.8, 'Ti West', 115, 'English', 1, 38000000.00, 'Paramount Pictures, Domain Entertainment, Wattsco, IN.2 FILM, Black Label Media', '', 11.39, '', 'https://image.tmdb.org/t/p/w500/z9UUbt2n5nzULfCP9gXbzIaZZQt.jpg', 1567605, 'tt38773219', 2, 0),
(31, 'Nie patrz w dół 2', 'Fall 2: Deadpoint', 'Thriller', 2026, 7.2, 'Michael Spierig', 98, 'English', 2, 3000000.00, 'Tea Shop Productions, Capstone Pictures, Flawless Production, Cousin Jones', '', 11.96, 'Przyjaciółki Grace Caroline Currey i Virginia Gardner ponownie wcielają się w swoje role. Ich umiejętności wspinaczkowe i determinacja do przetrwania zostają wystawione na próbę w ryzykownych sytuacjach na szczycie pustej, 600-metrowej wieży radiowej.\r Przytłoczona śmiercią siostry Hunter, Jax (Slater) nawiązuje kontakt z Luce (Thomas), nieustraszoną przyjaciółką Hunter. Aby się zregenerować, próbują pokonać słynną trasę po desce na górze Kwan w Tajlandii. Po nagłym osuwisku, który pozostawia ich na kruchej desce 900 metrów nad ziemią, Jax musi zmierzyć się ze swoimi najgłębszymi lękami i walczyć o przetrwanie, by znaleźć ukojenie.', 'https://image.tmdb.org/t/p/w500/2XTAPrXgZeHwGNrH3P48ojlbMJ.jpg', 1101412, 'tt31192372', 2, 0),
(32, 'Wyścig o miłość', 'Drive – The Pretenders', 'Romans, Thriller', 2026, 7.6, 'Sergej Moya', 101, 'Deutsch', 4, NULL, 'Bavaria Fiction, Wattpad, WEBTOON Entertainment', '', 13.66, 'Młoda pani mechanik samochodów wyścigowych, Sarah Jenkins, zostaje zatrudniona przez sztab Dantego Annunziaty – wschodzącej gwiazdy Formuły 1, wokół której nieustannie wybuchają skandale – aby wcieliła się w rolę jego narzeczonej. Ma to na celu poprawę jego wizerunku i odbudowę pozytywnego odbioru w oczach opinii publicznej. Dla Sarah oznacza to nie tylko atrakcyjne wynagrodzenie, ale także szansę na zaistnienie w świecie wyścigów jako kierowca. Związek, który początkowo jest jedynie udawany, przeradza się w coś znacznie poważniejszego, gdy między bohaterami niespodziewanie rodzą się prawdziwe uczucia.', 'https://image.tmdb.org/t/p/w500/eKeRcZ7otaDAR3uEtM1e4RcqIGy.jpg', 1596275, 'tt37180686', 2, 0),
(33, 'Ostatnia misja', 'The Fix', 'Akcja, Thriller', 2026, 5.8, 'Guy Moshe', 142, 'العربية, English', 2, 32000000.00, 'Astral Future, Dreamtime Entertainment, Oakhurst Entertainment, BondIt Media Capital, Blue Rider Pic', '', 7.08, 'Tucker (Zachary Levi), były funkcjonariusz sił paramilitarnych CIA, staje na czele grupy skompromitowanych agentów tej agencji, by odzyskać miliony dolarów utracone podczas przejęcia ambasady USA w Teheranie w 1979 roku. Kierując się wątpliwą wskazówką od swojego dawnego mentora Larry’ego (Liam Neeson) – u którego postępuje demencja – zespół przedostaje się do Iranu i musi zmierzyć się z niebezpiecznym labiryntem kłamstw oraz zagrożeń. W miarę jak sieć intryg się zacieśnia, zmieniają się sojusze i mnożą akty zdrady, wystawiając ludzi Tuckera na ciężką próbę w wyścigu o powodzenie misji... i o własne odkupienie.', 'https://image.tmdb.org/t/p/w500/jlP8XDjZN89GrpM3je5Uf8Grqx8.jpg', 1228834, 'tt9601292', 2, 0),
(34, 'Buddy', 'Buddy', 'Horror, Komedia, Fantasy', 2026, 6.8, 'Casper Kelly', 96, 'English, Español', 1, 3000000.00, 'BoulderLight Pictures, Low Spark Films, SIPUR, Substance', '1 nomination total', 7.92, 'Grupa dzieci zostaje uwięziona w surrealistycznym serialu dla dzieci.', 'https://image.tmdb.org/t/p/w500/1BdZbNvl1SfrrX8J9X5tQzN6Ivu.jpg', 1514026, 'tt37281055', 2, 0),
(35, 'Przebudzenie', 'El despertar', 'Horror, Akcja, Wojenny, Fantasy, Thriller', 2026, 6.5, 'Jaime Osorio Márquez', 96, 'Español, اردو', 2, NULL, 'Rhayuela Films', '', 10.30, '', 'https://image.tmdb.org/t/p/w500/w3YJx1PPPC6aiVKusxfc9QA0uYS.jpg', 1657630, 'tt39120306', 2, 0),
(36, 'O psie, który uratował święta', 'A Dog\'s Perfect Christmas', 'Komedia, Dramat', 2026, 7.2, 'Cathryn Michon', 102, 'English', 7, NULL, 'Fezziwig Studios', '', 12.30, 'Gdy problem zdrowotny rozdziela rodzinę Gossów, zdeterminowany pies Winstead robi wszystko, aby połączyć swoich ludzi przed Wigilią.', 'https://image.tmdb.org/t/p/w500/zvsNAohDHRWcGvbPSD7r3WojpKb.jpg', 1570488, 'tt38515310', 2, 0),
(37, 'Kroniki lasu. Wildwood', 'Wildwood', 'Animacja, Fantasy, Przygodowy', 2026, 8.5, 'Travis Knight', 132, 'English', 9, 100000000.00, 'LAIKA', '1 win total', 14.15, 'Nastoletnia Prue wyrusza do magicznego lasu, by odnaleźć porwanego brata i odkryć świat, o którego istnieniu nie miała pojęcia.', 'https://image.tmdb.org/t/p/w500/gGNOZLrDE6EiOAqxbROS1K0FjQb.jpg', 791523, 'tt2056785', 2, 0),
(38, 'The Anacondas', 'The Anacondas', 'Akcja, Przygodowy, Horror', 2025, 3.6, 'Marcel Walz', 90, 'English', 10, NULL, 'The Asylum, Atomic Blonde Entertainment, The Global Asylum, LLC., Dimension Pictures', '', 12.92, '', 'https://image.tmdb.org/t/p/w500/yphysF14qWFvrIbFVg3vEnbudwT.jpg', 1595325, 'tt38043316', 2, 0),
(39, 'Mroczny Rycerz', 'The Dark Knight', 'Akcja, Thriller, Kryminał', 2008, 8.5, 'Christopher Nolan', 152, 'English, 普通话', 1, 185000000.00, 'Warner Bros. Pictures, Legendary Pictures, Syncopy, DC', 'Won 2 Oscars. 164 wins & 165 nominations total', 14.43, 'Kontynuacja filmu \"Batman: Początek\", \"Mroczny Rycerz\", to kolejne wspólne dzieło reżysera Christophera Nolana i gwiazdora Christiana Bale\'a, który ponownie wciela się w postać Batmana / Bruce\'a Wayne\'a toczącego zażartą wojnę ze światem przestępczym. Batmanowi udaje się na dobre rozbić kryminalne podziemie Gotham z pomocą porucznika Jima Gordona (Gary Oldman) i Prokuratora Okręgowego Harveya Denta (Aaron Eckhart). Ich współpraca okazuje się niezwykle skuteczna, ale szybko trzej mężczyźni stają się celem nowego geniusza zbrodni, Jokera (Heath Ledger), którego celem jest wprowadzenie w Gotham anarchii i zmuszenie Batmana, by ten przeszedł na stronę zła, przestał być bohaterem, a stał się złoczyńcą.', 'https://image.tmdb.org/t/p/w500/gKMDmGde8aAD8M6dvm6j7wciSbJ.jpg', 155, 'tt0468569', 2, 0),
(40, 'Avengers: Koniec gry', 'Avengers: Endgame', 'Przygodowy, Sci-Fi, Akcja', 2019, 8.2, 'Joe Russo', 180, 'English, 日本語, ', 4, 356000000.00, 'Marvel Studios', 'Nominated for 1 Oscar. 71 wins & 132 nominations total', 12.25, 'Po dramatycznych wydarzeniach z filmu \"Avengers: Wojna bez granic\" Iron Man samotnie dryfuje po kosmosie, połowa superbohaterów przestała istnieć, a Kapitan Ameryka próbuje pogodzić się z porażką. Świat już nigdy nie będzie taki sam, a ocaleni muszą nauczyć się żyć w nowych warunkach. Nie wszyscy jednak dają za wygraną. Gdy w bazie Avengers pojawia się Ant-Man, w głowach herosów rodzi się szalony plan zmiany obecnego stanu rzeczy. Czy jest możliwe odwrócenie \"Efektu Thanosa\" i przywrócenie do naszego świata tych, co odeszli? Iron Man, Kapitan Ameryka, Thor, Hulk, Czarna Wdowa i pozostali zbierają się ponownie, żeby wyruszyć w pełną przygód podróż po najważniejszych momentach w historii Avengers.', 'https://image.tmdb.org/t/p/w500/7It0CFUs7MxZKzFFHQzyXeNs0C5.jpg', 299534, 'tt4154796', 3, 0),
(41, 'Naznaczony: Wyjście z mrocznego wymiaru', 'Insidious: Out of the Further', 'Horror, Thriller', 2026, 7.7, 'Jacob Chase', 106, 'English', 3, 18000000.00, 'Screen Gems, Stage 6 Films, Atomic Monster, TSG Entertainment, Blumhouse Atomic, Oren Peli Productio', '', 13.48, 'Gemma, młoda matka wychowująca córkę w swoim rodzinnym domu, odkrywa, że potrafi przenikać do Mrocznego Wymiaru (The Further) oraz sprowadzać stamtąd stworzenia do świata rzeczywistego.', 'https://image.tmdb.org/t/p/w500/toCKmrFAgxOfehUAxo59ATIEcdw.jpg', 1291595, 'tt32393988', 2, 0),
(42, 'Wojna światów', 'War of the Worlds', 'Sci-Fi, Thriller', 2025, 4.0, 'Rich Lee', 145, 'English', 6, 10000000.00, 'Universal Pictures, Bazelevs, Patrick Aiello Productions', '6 wins & 1 nomination total', 9.65, 'Will Radford jest czołowym analitykiem ds. cyberbezpieczeństwa w Homeland Security, który śledzi potencjalne zagrożenia dla bezpieczeństwa narodowego za pomocą programu masowej inwigilacji. Aż pewnego dnia atak nieznanej jednostki sprawia, że zaczyna się zastanawiać, czy rząd czegoś przed nim nie ukrywa... i przed resztą świata.', 'https://image.tmdb.org/t/p/w500/s20qugrUD5mPGQdyQ1LMLCYUOmy.jpg', 755898, 'tt13186306', 2, 0),
(43, 'Godzilla Minus One', 'ゴジラ-1.0', 'Sci-Fi, Horror, Akcja', 2023, 7.6, 'Takashi Yamazaki', 125, 'English, 日本語', 8, 15000000.00, 'TOHO, TOHO Studios, Robot Communications', 'Won 1 Oscar. 44 wins & 62 nominations total', 12.72, 'W powojennej Japonii były pilot myśliwca po traumatycznych przeżyciach dołącza do walki ze zmutowanym potworem, który atakuje wybrzeże kraju.', 'https://image.tmdb.org/t/p/w500/A5zamqZdjvPzUIGkEPLSH15BiRe.jpg', 940721, 'tt23289160', 3, 0),
(44, 'Street Fighter. Uliczny wojownik', 'Street Fighter', 'Akcja, Fantasy', 2026, 6.3, 'Kitao Sakurai', 125, 'English', 6, 82000000.00, 'Capcom, Legendary Pictures', '', 8.96, 'Akcja filmu rozgrywa się w 1993 roku. Skłóceni wojownicy Ryu i Ken Masters ponownie stają do walki, gdy tajemnicza Chun-Li rekrutuje ich do kolejnego turnieju World Warrior Tournament: brutalnej walki na pięści. Jednak za tą walką kryje się spisek, który zmusza ich do zmierzenia się ze sobą i demonami przeszłości. Jeśli tego nie zrobią, będzie to oznaczało koniec gry!', 'https://image.tmdb.org/t/p/w500/oMnncMmgzAhIAJ8I1gv0dugguQv.jpg', 1153576, 'tt27419420', 3, 0),
(45, 'Obsesja', 'Obsession', 'Horror, Thriller', 2026, 8.2, 'Curry Barker', 100, 'English', 4, 750000.00, 'Tea Shop Productions, Under the Shell, Capstone Pictures, Blumhouse Productions', '10 wins & 13 nominations total', 5.85, 'Bear platonicznie zakochany w swojej przyjaciółce Nikki, chce zdobyć serce ukochanej i postanawia spełnić swoje marzenie za pomocą taniej zabawki spełniające życzenia \"One Wish Willow\". Zabawka naprawdę działa i chłopak otrzymuje dokładnie to, o co prosił, ale wkrótce odkrywa, że niektóre pragnienia mają mroczną, złowrogą cenę.', 'https://image.tmdb.org/t/p/w500/yLMbHFNQ900b5M7kXujcJ5tkGrv.jpg', 1339713, 'tt37287335', 2, 0),
(46, 'Nie zasypiaj', 'Sleepwalker', 'Thriller, Horror', 2026, 4.4, 'Brandon Auman', 89, 'English', 9, NULL, 'Verdi Productions, Appian Way', '', 13.22, 'Pogrążona w żałobie matka, którą prześladuje tragiczna strata córki w wypadku samochodowym, w wyniku którego jej agresywny mąż zapadł w śpiączkę. Podczas gdy zmaga się z surrealistycznym pogrążaniem się w ciemności, jej epizody lunatykowania nasilają się. Dręczona nawiedzającymi ją wizjami męża w ich domu, zmaga się z zacierającą się granicą między rzeczywistością a koszmarem.', 'https://image.tmdb.org/t/p/w500/760SP4VsZagpyB9WLfeZykE3DFg.jpg', 1432306, 'tt35672651', 2, 0),
(47, 'Allen', 'Allen', 'Sci-Fi, Przygodowy, Komedia', 2026, 6.9, 'Daley Pearson', 105, 'English', 10, NULL, 'Ludo Studio, Screen Queensland, Queensland Government', '', 8.52, 'Najlepszy przyjaciel Peteya z dzieciństwa, kosmita o imieniu Allen, zniknął bez słowa pożegnania. Dwie dekady później Allen powraca z tajemnicą, która może odmienić świat, zmuszając Peteya do ostatecznego dorastania i udzielenia pomocy w jego ocaleniu.', 'https://image.tmdb.org/t/p/w500/alhhrpj1PSAn5bfz4Os1k7Bweoj.jpg', 1518204, 'tt37675123', 2, 0),
(48, 'Clayface', 'Clayface', 'Horror, Thriller, Sci-Fi', 2026, 7.4, 'James Watkins', 109, 'English', 9, 44000000.00, 'DC Studios, Domain Entertainment, 6th & Idaho Motion Picture Company, Troll Court Entertainment, The', '', 5.64, '„Clayface” ukazuje przerażającą przemianę mężczyzny z wschodzącej gwiazdy Hollywood w oszpeconą ofiarę szukającą zemsty, w historii, która zgłębia utratę człowieczeństwa i zniszczenie wynikające z wszechogarniającej obsesji.', 'https://image.tmdb.org/t/p/w500/9l1NuFjel2j89hiuiJbsxfblqjy.jpg', 1400940, 'tt34890576', 2, 0),
(49, 'Zapomniana Wyspa', 'Forgotten Island', 'Animacja, Przygodowy, Fantasy, Komedia, Familijny', 2026, 8.0, 'Januel Mercado', 109, 'English, ', 5, 80000000.00, 'DreamWorks Animation', '', 13.95, 'Podczas świętowania ostatniej wspólnej nocy, Jo i Raissa natrafiają na tajemniczy portal, który przenosi je na fantastyczną wyspę Nakali, pełną magicznych i mitycznych stworzeń, o których słuchały w opowieściach swoich filipińskich rodzin. Niektóre z tych postaci staną się przyjaciółmi, inne wrogami. Jo i Raissa muszą stawić czoła najgroźniejszemu stworzeniu na wyspie. Kiedy odkryją, że wspomnienia całej ich przyjaźni są ceną za powrót do domu, Jo i Raissa będą ścigać się, by znaleźć sposób na opuszczenie wyspy, zanim zapomną o sobie na zawsze.', 'https://image.tmdb.org/t/p/w500/qwadRpdhFWV7Pc7NKQq3JYZLrWf.jpg', 1465063, 'tt36583977', 2, 0),
(50, 'Buntownik', 'Mutiny', 'Akcja, Thriller', 2026, 7.6, 'Jean-François Richet', 95, 'English', 6, 40000000.00, 'Punch Palace Productions, MadRiver Pictures', '', 10.46, 'Cole Reed ma za sobą lata służby w policyjnych siłach specjalnych. Dziś działa w sektorze prywatnym jako ochroniarz potężnego miliardera. Ceni sobie dobre pieniądze i przewidywalność nowej pracy. Jednak, gdy jego mocodawca zostanie brutalnie zamordowany, Cole będzie musiał znów stanąć do walki z potężnym wrogiem. Ścigając zabójców trafi na trop międzynarodowego spisku handlarzy ludźmi, który sięga najwyższych kręgów władzy. W poszukiwaniu sprawiedliwości trafia na pokład statku przewożącego setki uprowadzonych kobiet i dzieci. To co miało być zemstą, stanie się walką o życie niewinnych.', 'https://image.tmdb.org/t/p/w500/nCjZMeioXxcVpaa7gBgKbjeOngw.jpg', 1288445, 'tt32338669', 2, 0),
(51, 'Kurs kolizyjny', 'Colisión', 'Thriller, Dramat, Kryminał', 2026, 6.4, 'Daniel Sánchez Arévalo', 122, 'Español, Português', 4, NULL, 'Bambú Producciones', '', 11.98, 'Hiszpania, rok 2013. Wypadek samochodu, którym złodzieje uciekają po obrabowaniu banku, odsłania to, co ukrywają - zdrady i kłamstwa, które zaczęły się dużo wcześniej.', 'https://image.tmdb.org/t/p/w500/sMPIiaOoyTr5o6s602KIVMJX3P2.jpg', 1571955, 'tt38793125', 2, 0),
(52, 'Sukienka', 'El vestido', 'Horror', 2026, 6.4, 'Jacob Santana', 75, 'Español, Português', 7, NULL, 'AF Films, Forgotten 2 Entertainment, S.L. Production, E-Media Canary Projects', '', 5.54, 'Po rozwodzie Alicia przeprowadza się z córką Carlą do odległego domu na wsi, mając nadzieję na odbudowanie swojego życia. Jednak to, co wydawało się nową szansą, wkrótce zamienia się w koszmar, gdy Carla znajduje na strychu tajemniczą niebieską sukienkę. Po jej założeniu dziewczynka zaczyna doświadczać dziwnych zdarzeń, słyszy szepczące głosy w ciemności, ma niepokojące wizje i narastającą obsesję na punkcie sukienki, która zdaje się mieć nadprzyrodzone powiązania. Kiedy okazuje się, że szata ma coś wspólnego z duchem dziewczyny z przeszłości, której tragedia wkrótce ma się powtórzyć, matka i córka zmuszone są stawić czoła nadprzyrodzonej sile.', 'https://image.tmdb.org/t/p/w500/2SoHOeFWgF4pP9yVlEch76ja7r5.jpg', 1474226, 'tt36822366', 3, 0),
(53, 'Dziki Koń Dziewięć', 'Wild Horse Nine', 'Komedia, Kryminał, Thriller', 2026, 7.9, 'Martin McDonagh', 118, 'English, Español', 9, 13000000.00, 'Searchlight Pictures, Blueprint Pictures, Film4 Productions, TSG Entertainment', '', 14.51, 'Krótko przed chilijskim zamachem stanu w 1973 roku, agenci CIA Chris i Lee zostają wysłani z Santiago na Wyspę Wielkanocną przez szefa swojego biura, MJ. Wśród kultowych posągów wyspy, a wieloletni partnerzy zmagają się z mroczną przeszłością i obecnymi spiskami, nowo odkryta więź Chrisa z parą zbuntowanych studentów grozi pokrzyżowaniem planów wszystkich uczestników wyprawy do tego odległego raju.', 'https://image.tmdb.org/t/p/w500/dNJFRtVg3xLQ7dbNIQ55cmmIniD.jpg', 891621, 'tt15799564', 2, 0),
(54, 'Toy Story 5', 'Toy Story 5', 'Animacja, Familijny, Komedia, Przygodowy', 2026, 8.3, 'Andrew Stanton', 102, 'English, Español', 10, 250000000.00, 'Pixar', '4 nominations total', 5.45, 'Praca Buzza, Chudego, Jessie i reszty ekipy staje się wykładniczo trudniejsza, gdy mierzą się z zupełnie nowym zagrożeniem dla zabawy: technologią.', 'https://image.tmdb.org/t/p/w500/1Yu8ILEVcUIVOPWJxGuPqgUdwD9.jpg', 1084244, 'tt29355505', 2, 0),
